src='''def find_boxes(g):
    Hl,Wl=len(g),len(g[0]); used=set(); res=[]
    for i in range(Hl):
        for j in range(Wl):
            c=g[i][j]
            if c and (i,j) not in used:
                j2=j
                while j2+1<Wl and g[i][j2+1]==c: j2+=1
                if j2-j+1<3: continue
                i2=i
                while i2+1<Hl and g[i2+1][j]==c: i2+=1
                if i2-i+1<3: continue
                border=[(i,x) for x in range(j,j2+1)]+[(i2,x) for x in range(j,j2+1)]+[(x,j) for x in range(i,i2+1)]+[(x,j2) for x in range(i,i2+1)]
                if all(g[a][b]==c for a,b in border) and not any(g[a][b]==c for a in range(i+1,i2) for b in range(j+1,j2)):
                    res.append([c,i,i2,j,j2])
                    for a in range(i,i2+1):
                        for b in range(j,j2+1): used.add((a,b))
    return res

def transform(grid):
    g=[row[:] for row in grid]
    B=find_boxes(g)
    allbox=set()
    for c,i1,i2,j1,j2 in B:
        for a in range(i1,i2+1):
            for b in range(j1,j2+1): allbox.add((a,b))
    dots={}
    for i in range(len(g)):
        for j in range(len(g[0])):
            c=g[i][j]
            if c and (i,j) not in allbox: dots.setdefault(c,[]).append((i,j))
    B.sort(key=lambda b:(b[2]-b[1]-1)*(b[4]-b[3]-1))
    cols=sorted(dots,key=lambda c:len(dots[c]))
    for (c,i1,i2,j1,j2),fc in zip(B,cols):
        for di in range(1,i2-i1):
            for dj in range(1,j2-j1):
                if (di+dj)%2==0: g[i1+di][j1+dj]=fc
        for a,b in dots[fc]: g[a][b]=0
    return g
'''
